const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const DBKEY='geopramForms.v1';
const starterForms=[
{id:'form-event-01',title:'Community Event Feedback',description:'Help us make the next event even better. This short survey takes about 2 minutes.',type:'survey',status:'published',created:'2026-10-08',responses:128,questions:[{id:'q1',type:'rating',label:'How would you rate the event overall?',required:true},{id:'q2',type:'choice',label:'What did you enjoy most?',required:true,options:['Speakers and sessions','Networking','Venue and organisation','Practical demonstrations']},{id:'q3',type:'long',label:'What could we improve next time?',required:false},{id:'q4',type:'email',label:'Email address (optional)',required:false}]},
{id:'form-field-02',title:'Field Data Collection',description:'Record site observations, location notes and supporting media.',type:'data',status:'draft',created:'2026-10-06',responses:42,questions:[{id:'q1',type:'text',label:'Site or location name',required:true},{id:'q2',type:'number',label:'Number of observations',required:true},{id:'q3',type:'choice',label:'Site condition',required:true,options:['Good','Fair','Needs attention']},{id:'q4',type:'media',label:'Attach a site photo',required:false}]},
{id:'form-quiz-03',title:'Geospatial Fundamentals Quiz',description:'A short knowledge check on maps, coordinate systems and spatial data.',type:'quiz',status:'published',created:'2026-10-02',responses:76,questions:[{id:'q1',type:'choice',label:'Which coordinate system is commonly used for local projected mapping in Kenya?',required:true,options:['WGS 84 geographic coordinates','UTM / WGS 84','Web Mercator only'],correct:'UTM / WGS 84'},{id:'q2',type:'choice',label:'What does GIS stand for?',required:true,options:['Geographic Information System','Global Internet Service','Ground Image Survey'],correct:'Geographic Information System'}]}
];starterForms.forEach((f,i)=>{f.owner='admin';f.ownerName='Geopram';f.code='GF-DEMO-000'+(i+1);f.approval='approved'});
function loadDB(){try{return JSON.parse(localStorage.getItem(DBKEY))||{forms:starterForms,responses:[]}}catch(e){return {forms:starterForms,responses:[]}}}
function saveDB(db){localStorage.setItem(DBKEY,JSON.stringify(db))}
function getDB(){let db=loadDB();if(!db.forms||!db.forms.length){db.forms=starterForms;saveDB(db)}return db}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){let t=$('#toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2500)}
function formIcon(type){return ({survey:'▤',quiz:'✎',data:'⌖',event:'▣'})[type]||'▤'}
function statusPill(status){return `<span class="pill ${status==='draft'?'draft':status==='closed'?'closed':''}">${esc(status||'draft')}</span>`}
function appShell(active,content){return `<div class="app-shell"><aside class="sidebar" id="sidebar"><div class="side-brand"><a class="brand" href="index.html"><img src="assets/geopram-logo.png" alt="Geopram Technologies"><div class="brand-name">GEOPRAM <span>FORMS</span><small>FORM & DATA STUDIO</small></div></a></div><div class="side-nav-label">Workspace</div><a class="side-link ${active==='dashboard'?'active':''}" href="dashboard.html"><span class="ico">▦</span>Dashboard</a><a class="side-link ${active==='forms'?'active':''}" href="dashboard.html#forms"><span class="ico">▤</span>My forms</a><a class="side-link ${active==='templates'?'active':''}" href="templates.html"><span class="ico">▧</span>Templates</a><a class="side-link ${active==='responses'?'active':''}" href="responses.html"><span class="ico">◷</span>Responses & insights</a><div class="side-nav-label">Manage</div><a class="side-link ${active==='settings'?'active':''}" href="settings.html"><span class="ico">⚙</span>Settings</a><a class="side-link" href="open.html"><span class="ico">⌗</span>Enter a form code</a><a class="side-link" href="../index.html"><span class="ico">↗</span>Visit website</a><div class="side-bottom"><div class="upgrade-box"><strong>Make every response count.</strong><p>Build forms for events, fieldwork, feedback and learning.</p><a href="builder.html" class="btn btn-primary btn-sm">＋ Create a form</a></div><p class="small" style="color:#738196;margin:18px 4px 0">GEOPRAM TECHNOLOGIES · KENYA</p></div></aside><main class="app-main"><header class="app-topbar"><div style="display:flex;align-items:center;gap:12px;min-width:0"><button class="menu-toggle mobile-sidebar-toggle" id="sidebarToggle" aria-label="Open navigation">☰</button><div class="top-search"><input id="globalSearch" placeholder="Search forms..." aria-label="Search forms"></div></div><div class="top-right"><button class="icon-btn" title="Help" onclick="toast('Tip: start with a template or create a blank form.')">?</button><div class="user-chip"><div class="avatar">${esc((GFU.name||'G')[0])}</div><div><strong>${esc(GFU.name)}</strong><small>${GFU.role==='admin'?'Administrator':'Tutor'}</small></div></div><button class="btn btn-outline btn-sm" id="gfOut">Log out</button></div></header><div class="app-content">${content}</div></main></div><div id="toast" class="toast"></div>`}
function renderFormRows(forms){if(!forms.length)return `<div class="empty-state"><div class="big">▤</div><h3>No forms found</h3><p>Create a form or change your search.</p><a class="btn btn-primary" href="builder.html">＋ Create a form</a></div>`;return `<div class="form-list">${forms.map(f=>`<div class="form-row" data-title="${esc(f.title.toLowerCase())}"><div class="form-thumb">${formIcon(f.type)}</div><div class="form-info"><strong>${esc(f.title)}</strong><small>${esc(f.type.toUpperCase())} · Updated ${esc(f.created||'Today')} · ${f.questions?.length||0} questions · Code ${esc(f.code||'-')}</small></div>${statusPill(f.status)}${apprPill(f)}<div class="row-actions"><span class="small muted">◉ ${f.responses||0}</span><button class="btn btn-outline btn-sm" data-copy="${esc(f.code||'')}">Copy code</button><a class="btn btn-outline btn-sm" href="builder.html?id=${encodeURIComponent(f.id)}">Edit</a><a class="btn btn-outline btn-sm" href="preview.html?id=${encodeURIComponent(f.id)}" target="_blank">Open</a><button class="icon-btn" data-delete="${esc(f.id)}" title="Delete form">⌫</button></div></div>`).join('')}</div>`}
function bindShell(){const toggle=$('#sidebarToggle');if(toggle)toggle.addEventListener('click',()=>$('#sidebar').classList.toggle('open'));const search=$('#globalSearch');if(search)search.addEventListener('input',()=>$$('.form-row').forEach(row=>row.style.display=row.dataset.title.includes(search.value.toLowerCase())?'flex':'none'));$$('[data-delete]').forEach(b=>b.addEventListener('click',()=>{if(confirm('Delete this form? This cannot be undone.')){let db=getDB();db.forms=db.forms.filter(f=>f.id!==b.dataset.delete);saveDB(db);location.reload()}}))}
function initDashboard(){const db=getDB(),forms=myForms(db);const content=`<div class="page-heading"><div><div class="eyebrow">Your workspace</div><h1>Good work starts with good questions.</h1><p>Create, share and learn from forms in one place.</p></div><div class="page-actions"><a class="btn btn-outline" href="templates.html">Browse templates</a><a class="btn btn-primary" href="builder.html">＋ Create a form</a></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Total responses <span class="stat-bubble">◉</span></div><strong>${forms.reduce((n,f)=>n+(f.responses||0),0)+db.responses.filter(r=>forms.some(f=>f.id===r.formId)).length}</strong><span class="stat-change">Across your workspace</span></div><div class="stat-card"><div class="stat-top">Forms created <span class="stat-bubble">▤</span></div><strong>${forms.length}</strong><span class="stat-change">Your form library</span></div><div class="stat-card"><div class="stat-top">Published forms <span class="stat-bubble">↗</span></div><strong>${forms.filter(f=>f.status==='published').length}</strong><span class="stat-change">Ready to share</span></div><div class="stat-card"><div class="stat-top">Drafts <span class="stat-bubble">✎</span></div><strong>${forms.filter(f=>f.status==='draft').length}</strong><span class="stat-change">Still in progress</span></div></div>${approvalPanel(db)}<div class="dashboard-grid"><section class="panel"><div class="panel-heading"><h3>Recent forms</h3><a href="#forms" class="small" style="color:var(--red);font-weight:800">View all →</a></div>${renderFormRows(forms.slice(0,3))}</section><section class="panel"><div class="panel-heading"><h3>Quick start</h3><span class="small muted">Choose a path</span></div><div class="activity-row"><div class="activity-icon">▤</div><div class="activity-copy"><strong>Customer & event feedback</strong><small>Ratings, comments and satisfaction</small></div><a class="btn btn-outline btn-sm" href="builder.html?type=survey">Create</a></div><div class="activity-row"><div class="activity-icon">⌖</div><div class="activity-copy"><strong>Field data collection</strong><small>Observations, GPS notes and media</small></div><a class="btn btn-outline btn-sm" href="builder.html?type=data">Create</a></div><div class="activity-row"><div class="activity-icon">✎</div><div class="activity-copy"><strong>Quiz or assessment</strong><small>Questions, answer keys and scoring</small></div><a class="btn btn-outline btn-sm" href="builder.html?type=quiz">Create</a></div></section></div><section id="forms" style="margin-top:24px"><div class="panel-heading"><h3>All forms</h3><span class="small muted">${forms.length} forms in workspace</span></div>${renderFormRows(forms)}</section>`;document.body.innerHTML=appShell('dashboard',content);bindShell()}
const questionTypes=[['text','Short answer','Aa'],['long','Paragraph','¶'],['choice','Multiple choice','◉'],['multi','Checkboxes','☑'],['dropdown','Dropdown','▾'],['rating','Rating scale','☆'],['number','Number','№'],['date','Date','▦'],['email','Email','✉'],['media','Image / file','▧'],['video','Video link','▷'],['location','Location / coordinates','⌖']];
let editorForm=null,selectedQuestion=null;
function newId(){return 'q'+Math.random().toString(36).slice(2,9)}
function initBuilder(){const db=getDB(),params=new URLSearchParams(location.search),id=params.get('id'),type=params.get('type')||'survey';editorForm=id?db.forms.find(f=>f.id===id&&canEdit(f)):null;if(!editorForm){editorForm={id:'form-'+Date.now(),owner:GFU.email,ownerName:GFU.name,code:genCode(),approval:GFU.role==='admin'?'approved':'pending',title:'Untitled form',description:'Add a short description to explain what this form is for.',type,status:'draft',created:new Date().toISOString().slice(0,10),responses:0,questions:[]}}else editorForm=JSON.parse(JSON.stringify(editorForm));selectedQuestion=editorForm.questions[0]?.id||null;renderBuilder();bindBuilder()}
function renderBuilder(){const q=editorForm.questions;const tools=questionTypes.map(t=>`<button class="tool-button" data-add="${t[0]}"><span>${t[2]}</span>${t[1]}</button>`).join('');const cards=q.map((item,i)=>questionCard(item,i)).join('');const content=`<div class="page-heading"><div><div class="eyebrow">Form studio</div><h1>Form builder</h1><p>Shape the questions. Set the rules. Then share it with the world.</p></div><div class="page-actions"><a class="btn btn-outline" href="dashboard.html">Cancel</a><button class="btn btn-outline" id="previewBtn">◉ Preview</button><button class="btn btn-primary" id="saveBtn">Save form</button></div></div><div class="builder-layout"><aside class="builder-tools"><h3>＋ Add a question</h3><div class="tool-grid">${tools}</div><div class="notice" style="margin-top:16px">Media uploads are stored in this browser prototype. Add a backend for shared cloud storage.</div><button class="btn btn-outline btn-sm" style="width:100%" id="addSection">＋ Add section</button></aside><section class="builder-canvas"><div class="builder-cover"></div><div class="form-settings-head"><input id="formTitle" value="${esc(editorForm.title)}" aria-label="Form title" maxlength="120"><textarea id="formDescription" aria-label="Form description" placeholder="Describe this form...">${esc(editorForm.description||'')}</textarea><div style="display:flex;gap:8px;flex-wrap:wrap"><span class="pill">${esc(editorForm.type.toUpperCase())}</span><span class="pill draft">Autosave is manual</span></div></div><div id="questionList">${cards}</div><button class="add-question" id="addFirst">＋ Add your first question</button><div class="builder-footer"><span class="muted">${q.length} question${q.length===1?'':'s'} · Changes stay in this browser until saved</span><button class="btn btn-primary" id="saveBottom">Save form</button></div></section><aside class="builder-settings"><h3>Form settings</h3><div><label class="field-label">Form type</label><select id="formType" class="field-control"><option value="survey">Survey / feedback</option><option value="event">Event registration</option><option value="data">Field data collection</option><option value="quiz">Quiz / assessment</option></select><label class="field-label">Theme colour</label><select id="themeColor" class="field-control"><option value="#ed101b">Geopram red</option><option value="#2478ee">Ocean blue</option><option value="#16845b">Field green</option><option value="#081321">Midnight</option></select><label class="field-label">Confirmation message</label><textarea id="confirmation" class="field-control" rows="3">${esc(editorForm.confirmation||'Thank you. Your response has been recorded.')}</textarea><label class="check-row"><input id="collectEmail" type="checkbox" ${editorForm.collectEmail?'checked':''}> Collect respondent email</label><label class="check-row"><input id="showProgress" type="checkbox" ${editorForm.showProgress!==false?'checked':''}> Show progress indicator</label><label class="check-row"><input id="shuffle" type="checkbox" ${editorForm.shuffle?'checked':''}> Shuffle quiz questions</label><label class="field-label">Status</label><select id="formStatus" class="field-control"><option value="draft">Draft</option><option value="published">Published</option><option value="closed">Closed</option></select><label class="field-label">Form code</label><input class="field-control" readonly value="${esc(editorForm.code||'')}"><p class="small muted">Approval: <b>${esc(editorForm.approval||'approved')}</b>. Tutor forms go live after Geopram approves them. Share the code only with the people who should respond.</p><p class="small muted" style="margin-top:14px">Publishing makes the preview page accept local demo responses. A production deployment needs a secure database and server.</p></div></aside></div>`;document.body.innerHTML=appShell('forms',content);$('#formType').value=editorForm.type;$('#formStatus').value=editorForm.status;$('#addFirst').style.display=q.length?'none':'block';}
function questionCard(item,i){const choices=['choice','multi','dropdown'].includes(item.type);let preview='';if(item.type==='text'||item.type==='email'||item.type==='number'||item.type==='date')preview=`<input disabled placeholder="${item.type==='date'?'Select a date':'Short answer'}" type="${item.type==='text'?'text':item.type}">`;else if(item.type==='long')preview='<textarea disabled placeholder="Long answer"></textarea>';else if(choices)preview=(item.options||['Option 1','Option 2']).map((o,j)=>`<div class="option-line"><span>${item.type==='multi'?'☐':item.type==='dropdown'?'▾':'◯'}</span><input type="text" data-option="${item.id}" data-index="${j}" value="${esc(o)}"><button class="icon-btn" data-remove-option="${item.id}" data-index="${j}">×</button></div>`).join('')+`<button class="btn btn-ghost btn-sm" data-add-option="${item.id}">＋ Add option</button>`;else if(item.type==='rating')preview='<div style="font-size:25px;letter-spacing:7px;color:#ed101b">☆ ☆ ☆ ☆ ☆</div>';else if(item.type==='media')preview=`<div class="media-drop">▧ Upload image or file<br><input type="file" data-media="${item.id}" accept="image/*,video/*,.pdf,.doc,.docx" multiple></div>`;else if(item.type==='video')preview='<input disabled placeholder="Paste a video URL">';else if(item.type==='location')preview='<input disabled placeholder="Coordinates or location name">';return `<article class="question-card ${selectedQuestion===item.id?'selected':''}" data-qcard="${item.id}"><div class="question-card-top"><small>QUESTION ${i+1} · ${esc(item.type.toUpperCase())}</small><button class="icon-btn" data-select="${item.id}" title="Select question">⋮</button></div><input class="question-label" data-label="${item.id}" value="${esc(item.label)}" aria-label="Question text"><div class="question-preview">${preview}</div><label class="check-row"><input type="checkbox" data-required="${item.id}" ${item.required?'checked':''}> Required question</label>${editorForm.type==='quiz'&&choices?`<label class="field-label">Correct answer (for quiz scoring)</label><select class="field-control" data-correct="${item.id}">${(item.options||[]).map(o=>`<option ${o===item.correct?'selected':''}>${esc(o)}</option>`).join('')}</select>`:''}<div class="question-tools"><button class="icon-btn" data-duplicate="${item.id}">▣ Duplicate</button><button class="icon-btn" data-up="${item.id}">↑</button><button class="icon-btn" data-down="${item.id}">↓</button><button class="icon-btn" data-delete-q="${item.id}">⌫ Delete</button></div></article>`}
function addQuestion(type){const item={id:newId(),type,label:({text:'Short answer question',long:'Tell us more',choice:'Choose one option',multi:'Select all that apply',dropdown:'Select an option',rating:'How would you rate this?',number:'Enter a number',date:'Choose a date',email:'What is your email address?',media:'Upload an image or file',video:'Share a video link',location:'Enter location or coordinates'})[type]||'New question',required:false};if(['choice','multi','dropdown'].includes(type))item.options=['Option 1','Option 2'];if(editorForm.type==='quiz'&&item.options)item.correct=item.options[0];editorForm.questions.push(item);selectedQuestion=item.id;renderBuilder();bindBuilder()}
function bindBuilder(){const type=$('#formType');if(type)type.addEventListener('change',()=>{editorForm.type=type.value;renderBuilder();bindBuilder()});$$('[data-add]').forEach(b=>b.addEventListener('click',()=>addQuestion(b.dataset.add)));$('#addFirst')?.addEventListener('click',()=>addQuestion('text'));$('#addSection')?.addEventListener('click',()=>{toast('Section break added as a planning note in this prototype.')});$$('[data-label]').forEach(el=>el.addEventListener('input',()=>{let q=editorForm.questions.find(q=>q.id===el.dataset.label);if(q)q.label=el.value}));$$('[data-required]').forEach(el=>el.addEventListener('change',()=>{let q=editorForm.questions.find(q=>q.id===el.dataset.required);if(q)q.required=el.checked}));$$('[data-option]').forEach(el=>el.addEventListener('change',()=>{let q=editorForm.questions.find(q=>q.id===el.dataset.option);if(q){q.options[+el.dataset.index]=el.value;if(q.correct===undefined)q.correct=q.options[0];}}));$$('[data-add-option]').forEach(b=>b.addEventListener('click',()=>{let q=editorForm.questions.find(q=>q.id===b.dataset.addOption);if(q){q.options.push('Option '+(q.options.length+1));renderBuilder();bindBuilder()}}));$$('[data-remove-option]').forEach(b=>b.addEventListener('click',()=>{let q=editorForm.questions.find(q=>q.id===b.dataset.removeOption);if(q&&q.options.length>1){q.options.splice(+b.dataset.index,1);renderBuilder();bindBuilder()}}));$$('[data-correct]').forEach(el=>el.addEventListener('change',()=>{let q=editorForm.questions.find(q=>q.id===el.dataset.correct);if(q)q.correct=el.value}));$$('[data-select]').forEach(b=>b.addEventListener('click',()=>{selectedQuestion=b.dataset.select;renderBuilder();bindBuilder()}));$$('[data-delete-q]').forEach(b=>b.addEventListener('click',()=>{editorForm.questions=editorForm.questions.filter(q=>q.id!==b.dataset.deleteQ);renderBuilder();bindBuilder()}));$$('[data-duplicate]').forEach(b=>b.addEventListener('click',()=>{let q=editorForm.questions.find(q=>q.id===b.dataset.duplicate);if(q){let copy=JSON.parse(JSON.stringify(q));copy.id=newId();copy.label+=' (copy)';editorForm.questions.push(copy);selectedQuestion=copy.id;renderBuilder();bindBuilder()}}));$$('[data-up]').forEach(b=>b.addEventListener('click',()=>moveQuestion(b.dataset.up,-1)));$$('[data-down]').forEach(b=>b.addEventListener('click',()=>moveQuestion(b.dataset.down,1)));$$('[data-media]').forEach(el=>el.addEventListener('change',()=>{const q=editorForm.questions.find(q=>q.id===el.dataset.media);if(q){q.mediaNames=[...el.files].map(f=>f.name);toast('Selected '+q.mediaNames.length+' file(s). Files are not uploaded to a server in this demo.')}}));$('#saveBtn')?.addEventListener('click',saveForm);$('#saveBottom')?.addEventListener('click',saveForm);$('#previewBtn')?.addEventListener('click',()=>{syncFormFields();saveForm(true);window.open('preview.html?id='+encodeURIComponent(editorForm.id),'_blank')});}
function moveQuestion(id,dir){let i=editorForm.questions.findIndex(q=>q.id===id),j=i+dir;if(j<0||j>=editorForm.questions.length)return;[editorForm.questions[i],editorForm.questions[j]]=[editorForm.questions[j],editorForm.questions[i]];renderBuilder();bindBuilder()}
function syncFormFields(){editorForm.title=$('#formTitle').value.trim()||'Untitled form';editorForm.description=$('#formDescription').value;editorForm.type=$('#formType').value;editorForm.status=$('#formStatus').value;editorForm.confirmation=$('#confirmation').value;editorForm.collectEmail=$('#collectEmail').checked;editorForm.showProgress=$('#showProgress').checked;editorForm.shuffle=$('#shuffle').checked;editorForm.theme=$('#themeColor').value}
function saveForm(quiet=false){syncFormFields();if(!editorForm.questions.length){if(!quiet)toast('Add at least one question before saving.');return}let db=getDB(),i=db.forms.findIndex(f=>f.id===editorForm.id);if(i>=0)db.forms[i]=editorForm;else db.forms.unshift(editorForm);saveDB(db);if(!quiet)toast('Form saved in this browser.');}
function initTemplates(){const templates=[{title:'Event feedback survey',desc:'Collect attendee feedback, session ratings and suggestions.',type:'survey',tone:'red',icon:'▤',n:6},{title:'Event registration',desc:'Gather attendee details, preferences and attendance needs.',type:'event',tone:'blue',icon:'▣',n:7},{title:'Field observation log',desc:'Record site conditions, observations and media attachments.',type:'data',tone:'green',icon:'⌖',n:8},{title:'Knowledge check quiz',desc:'Create multiple-choice questions with answer keys.',type:'quiz',tone:'dark',icon:'✎',n:5},{title:'Customer satisfaction',desc:'Understand customer experience with ratings and comments.',type:'survey',tone:'red',icon:'☆',n:5},{title:'Research questionnaire',desc:'Structure research questions and capture consistent responses.',type:'data',tone:'blue',icon:'▥',n:10}];const content=`<div class="page-heading"><div><div class="eyebrow">Start with a framework</div><h1>Templates that get you moving.</h1><p>Choose a practical starting point and make it your own.</p></div><a href="builder.html" class="btn btn-primary">＋ Blank form</a></div><div class="tabs"><button class="tab active" data-filter="all">All templates</button><button class="tab" data-filter="survey">Surveys</button><button class="tab" data-filter="event">Events</button><button class="tab" data-filter="data">Field data</button><button class="tab" data-filter="quiz">Quizzes</button></div><div class="template-grid">${templates.map(t=>`<article class="template-card" data-template-type="${t.type}"><div class="template-preview ${t.tone}"><span style="font-size:25px;color:${t.tone==='dark'?'white':'var(--red)'}">${t.icon}</span></div><div class="template-body"><h3 style="font-size:16px">${t.title}</h3><p>${t.desc}</p><div class="template-meta"><span>${t.n} suggested questions</span><button class="btn btn-outline btn-sm" data-use-template="${t.type}" data-template-title="${t.title}">Use template →</button></div></div></article>`).join('')}</div>`;document.body.innerHTML=appShell('templates',content);bindShell();$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{$$('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');$$('[data-template-type]').forEach(c=>c.style.display=b.dataset.filter==='all'||c.dataset.templateType===b.dataset.filter?'block':'none')}));$$('[data-use-template]').forEach(b=>b.addEventListener('click',()=>{const type=b.dataset.useTemplate,title=b.dataset.templateTitle;let db=getDB(),f={id:'form-'+Date.now(),owner:GFU.email,ownerName:GFU.name,code:genCode(),approval:GFU.role==='admin'?'approved':'pending',title,description:'Use this template as a starting point. Edit the text to fit your project.',type,status:'draft',created:new Date().toISOString().slice(0,10),responses:0,questions:[]};let defaults=type==='quiz'?[['choice','Which answer is correct?',['Option A','Option B','Option C']],['choice','Select the best response',['Option 1','Option 2']]]:type==='data'?[['text','Site or record name'],['location','Location / coordinates'],['media','Attach supporting photo'],['long','Additional observations']]:type==='event'?[['text','Full name'],['email','Email address'],['choice','Which session will you attend?',['Session A','Session B','All sessions']],['multi','Any access requirements?',['None','Step-free access','Other']]]:[['rating','How would you rate your experience?'],['choice','What worked best?',['Content','Organisation','Support']],['long','What could we improve?']];f.questions=defaults.map(([t,l,o])=>({id:newId(),type:t,label:l,required:false,...(o?{options:o}:{}),...(type==='quiz'&&o?{correct:o[0]}:{})}));db.forms.unshift(f);saveDB(db);location.href='builder.html?id='+encodeURIComponent(f.id)}))}
function initPreview(){const db=getDB(),id=new URLSearchParams(location.search).get('id'),f=db.forms.find(x=>x.id===id);if(f&&!gfAccess(f))return gfCodeGate(f);if(!f){document.body.innerHTML='<div class="empty-state"><h3>No form found</h3><a href="builder.html">Create a form</a></div>';return}document.body.innerHTML=`<div class="form-public"><div class="public-top"><div class="container"><a class="brand" href="index.html"><img src="assets/geopram-logo.png" alt="Geopram Technologies"><div class="brand-name">GEOPRAM <span>FORMS</span><small>POWERED BY GEOPRAM TECHNOLOGIES</small></div></a></div></div><form class="public-wrap" id="publicForm"><div class="public-form-head" style="border-top-color:${esc(f.theme||'#ed101b')}"><span class="eyebrow">${esc(f.type.toUpperCase())}</span><h1>${esc(f.title)}</h1><p class="muted">${esc(f.description||'')}</p>${f.showProgress!==false?'<div style="height:4px;background:#edf0f5;border-radius:9px;margin-top:20px"><div id="progressFill" style="height:100%;width:0;background:var(--red);border-radius:9px"></div></div>':''}<p class="small muted" style="margin:14px 0 0">Questions marked with <span class="required">*</span> are required.</p></div>${f.collectEmail?'<div class="public-question"><label class="title" for="respondentEmail">Your email <span class="required">*</span></label><input class="public-control" type="email" id="respondentEmail" required></div>':''}${f.questions.map((q,i)=>publicQuestion(q,i)).join('')}<div class="public-question" style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap"><span class="small muted">Powered by Geopram Technologies</span><button class="btn btn-primary" type="submit">${f.type==='quiz'?'Submit answers':'Submit response'} →</button></div></form><div class="public-wrap" id="successWrap" hidden><div class="success-box"><div class="success-check">✓</div><h2>Response received</h2><p class="muted">${esc(f.confirmation||'Thank you. Your response has been recorded.')}</p><a href="index.html" class="btn btn-outline">Learn about Geopram Forms</a></div></div></div>`;const form=$('#publicForm');form.addEventListener('input',()=>{let total=f.questions.length,filled=f.questions.filter(q=>{let el=form.querySelector(`[name="${q.id}"]`);return el&&(el.value||form.querySelectorAll(`[name="${q.id}"]:checked`).length)}).length;const bar=$('#progressFill');if(bar)bar.style.width=(total?filled/total*100:0)+'%'});form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const answers={};f.questions.forEach(q=>{if(q.type==='multi')answers[q.id]=$$(`[name="${q.id}"]:checked`,form).map(x=>x.value);else if(q.type==='media')answers[q.id]=form.querySelector(`[name="${q.id}"]`)?.files?.length?[...form.querySelector(`[name="${q.id}"]`).files].map(x=>x.name):[];else if(q.type==='rating')answers[q.id]=form.querySelector(`[name="${q.id}"]:checked`)?.value||'';else answers[q.id]=form.querySelector(`[name="${q.id}"]`)?.value||''});let score=null;if(f.type==='quiz'){let graded=f.questions.filter(q=>q.correct);score=graded.filter(q=>answers[q.id]===q.correct).length}let db=getDB();if(f.owner!==GFU.email&&db.responses.some(r=>r.formId===f.id&&r.user===GFU.email)){toast('You have already responded to this form.');return}db.responses.push({id:'resp-'+Date.now(),formId:f.id,formTitle:f.title,user:GFU.email,name:GFU.name,submitted:new Date().toISOString(),answers,score,email:$('#respondentEmail')?.value||''});let stored=db.forms.find(x=>x.id===f.id);if(stored)stored.responses=(stored.responses||0)+1;saveDB(db);form.hidden=true;$('#successWrap').hidden=false;if(score!==null)$('#successWrap .muted').textContent=`You scored ${score} out of ${f.questions.filter(q=>q.correct).length}. `+ (f.confirmation||'Thank you for completing this quiz.');window.scrollTo({top:0,behavior:'smooth'})})}
function publicQuestion(q,i){let required=q.required?'required':'';let title=`<label class="title" for="field-${q.id}">${i+1}. ${esc(q.label)} ${q.required?'<span class="required">*</span>':''}</label>`;let field='';if(['text','email','number','date'].includes(q.type))field=`<input class="public-control" id="field-${q.id}" name="${q.id}" type="${q.type==='text'?'text':q.type}" ${required} placeholder="${q.type==='date'?'Choose a date':'Your answer'}">`;else if(q.type==='long')field=`<textarea class="public-control" id="field-${q.id}" name="${q.id}" rows="4" ${required} placeholder="Type your answer"></textarea>`;else if(['choice','multi','dropdown'].includes(q.type)){if(q.type==='dropdown')field=`<select class="public-control" id="field-${q.id}" name="${q.id}" ${required}><option value="">Select an option</option>${(q.options||[]).map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join('')}</select>`;else field=(q.options||[]).map(o=>`<label class="choice"><input type="${q.type==='multi'?'checkbox':'radio'}" name="${q.id}" value="${esc(o)}" ${q.type==='choice'?required:''}> ${esc(o)}</label>`).join('')+(q.type==='multi'&&q.required?`<input type="text" aria-label="Required checkbox validation helper" required style="position:absolute;width:1px;height:1px;opacity:0;pointer-events:none" oninvalid="this.setCustomValidity('Please select at least one option.')" oninput="this.setCustomValidity('')">`: '');}else if(q.type==='rating')field=`<div style="display:flex;gap:10px;flex-wrap:wrap">${[1,2,3,4,5].map(n=>`<label class="choice"><input type="radio" name="${q.id}" value="${n}" ${required}> ${n} ${n===1?'(Low)':n===5?'(Excellent)':''}</label>`).join('')}</div>`;else if(q.type==='media')field=`<input class="public-control" id="field-${q.id}" name="${q.id}" type="file" accept="image/*,video/*,.pdf,.doc,.docx" multiple ${required}><p class="small muted">Choose a photo or file from this device.</p>`;else if(q.type==='video')field=`<input class="public-control" id="field-${q.id}" name="${q.id}" type="url" placeholder="https://..." ${required}>`;else if(q.type==='location')field=`<input class="public-control" id="field-${q.id}" name="${q.id}" placeholder="Place name or latitude, longitude" ${required}>`;return `<div class="public-question">${title}${field}</div>`}
function initResponses(){const db=getDB(),forms=myForms(db),ids=forms.map(f=>f.id),responses=(db.responses||[]).filter(r=>ids.includes(r.formId));const content=`<div class="page-heading"><div><div class="eyebrow">Listen, learn, improve</div><h1>Responses & insights</h1><p>Explore submissions collected in this browser prototype.</p></div><div class="page-actions"><button class="btn btn-outline" id="exportResponses">↓ Export CSV</button><a class="btn btn-primary" href="builder.html">＋ Create a form</a></div></div><div class="stats-grid"><div class="stat-card"><div class="stat-top">Saved demo responses</div><strong>${responses.length}</strong><span class="stat-change">Submitted on this browser</span></div><div class="stat-card"><div class="stat-top">Forms with responses</div><strong>${forms.filter(f=>(f.responses||0)>0).length}</strong><span class="stat-change">Includes sample counts</span></div><div class="stat-card"><div class="stat-top">Quiz submissions</div><strong>${responses.filter(r=>r.score!==null&&r.score!==undefined).length}</strong><span class="stat-change">Scored assessments</span></div><div class="stat-card"><div class="stat-top">Latest submission</div><strong style="font-size:17px">${responses.length?new Date(responses[responses.length-1].submitted).toLocaleDateString():'—'}</strong><span class="stat-change">Local browser data</span></div></div><div class="panel"><div class="panel-heading"><h3>Submission history</h3><select id="responseFilter" class="field-control" style="width:auto;max-width:220px"><option value="all">All forms</option>${forms.map(f=>`<option value="${f.id}">${esc(f.title)}</option>`).join('')}</select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Form</th><th>Submitted</th><th>Respondent</th><th>Quiz score</th><th>Answers</th></tr></thead><tbody id="responseRows">${responseRows(responses)}</tbody></table></div></div><div class="notice" style="margin-top:18px">Sample response counts on the dashboard are illustrative starter data. Real submissions from this prototype are stored only in your current browser; they are not synced between devices.</div>`;document.body.innerHTML=appShell('responses',content);bindShell();$('#responseFilter').addEventListener('change',()=>{$('#responseRows').innerHTML=responseRows(responses.filter(r=>$('#responseFilter').value==='all'||r.formId===$('#responseFilter').value))});$('#exportResponses').addEventListener('click',()=>{const rows=[['Form','Submitted','Email','Score','Answers'],...responses.map(r=>[r.formTitle,r.submitted,r.email,r.score===null?'':r.score,JSON.stringify(r.answers)])];downloadCSV(rows,'geopram-responses.csv')})}
function responseRows(rs){if(!rs.length)return '<tr><td colspan="5" style="text-align:center;padding:40px;color:var(--muted)">No real submissions yet. Open a published form and submit a test response.</td></tr>';return rs.slice().reverse().map(r=>`<tr><td><strong>${esc(r.formTitle)}</strong></td><td>${new Date(r.submitted).toLocaleString()}</td><td>${esc(r.name?r.name+' ('+(r.user||'')+')':(r.email||'Anonymous'))}</td><td>${r.score===null||r.score===undefined?'—':esc(r.score)}</td><td>${Object.keys(r.answers||{}).length} fields</td></tr>`).join('')}
function downloadCSV(rows,name){const csv=rows.map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');const blob=new Blob([csv],{type:'text/csv;charset=utf-8;'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url)}
function initSettings(){const content=`<div class="page-heading"><div><div class="eyebrow">Workspace preferences</div><h1>Settings</h1><p>Manage how your Geopram Forms workspace behaves.</p></div><button class="btn btn-primary" id="saveSettings">Save preferences</button></div><div class="settings-grid"><nav class="settings-nav"><button class="active">General</button><button>Branding</button><button>Notifications</button><button>Privacy & data</button><button>About</button></nav><section class="settings-panel"><h3>General workspace</h3><p class="muted small">A few details to make the workspace yours.</p><label class="field-label">Workspace name</label><input class="field-control" id="workspaceName" value="Geopram Technologies"><label class="field-label">Contact email</label><input class="field-control" id="workspaceEmail" type="email" placeholder="hello@yourorganisation.com"><label class="field-label">Default form language</label><select class="field-control" id="language"><option>English</option><option>Kiswahili</option></select><div class="setting-row"><div><strong>Allow anonymous responses</strong><p>Let people respond without entering their email address.</p></div><input class="switch" type="checkbox" id="anonymous" checked></div><div class="setting-row"><div><strong>Show Geopram branding</strong><p>Display Geopram Technologies attribution on public forms.</p></div><input class="switch" type="checkbox" id="branding" checked></div><div class="setting-row"><div><strong>Quiz score feedback</strong><p>Show the score after a quiz is submitted.</p></div><input class="switch" type="checkbox" id="quizFeedback" checked></div><div class="setting-row"><div><strong>Store data on this device</strong><p>This standalone prototype uses browser storage. A production system should use secure server storage, access controls and backups.</p></div><span class="pill closed">Local demo</span></div><div class="notice" style="margin-top:20px">This is a front-end prototype, not a secure multi-user service. Do not collect sensitive personal or confidential data until a backend, authentication, consent and data-retention controls are implemented.</div><button class="btn btn-outline" id="resetDemo">Reset demo data</button></section></div>`;document.body.innerHTML=appShell('settings',content);bindShell();const stored=JSON.parse(localStorage.getItem('geopramSettings')||'{}');Object.keys(stored).forEach(k=>{let el=$('#'+k);if(el)el.type==='checkbox'?el.checked=stored[k]:el.value=stored[k]});$('#saveSettings').addEventListener('click',()=>{let obj={};['workspaceName','workspaceEmail','language','anonymous','branding','quizFeedback'].forEach(k=>{let el=$('#'+k);obj[k]=el.type==='checkbox'?el.checked:el.value});localStorage.setItem('geopramSettings',JSON.stringify(obj));toast('Preferences saved on this browser.')});$('#resetDemo').addEventListener('click',()=>{if(confirm('Reset forms, responses and preferences to the original demo state?')){localStorage.removeItem(DBKEY);localStorage.removeItem('geopramSettings');location.reload()}});$$('.settings-nav button').forEach(b=>b.addEventListener('click',()=>{if(b.textContent!=='General')toast('This section is planned for the next build.');$$('.settings-nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active')}))}
function initLanding(){const content=`<nav class="site-nav"><div class="container nav-inner"><a class="brand" href="index.html"><img src="assets/geopram-logo.png" alt="Geopram Technologies logo"><div class="brand-name">GEOPRAM <span>FORMS</span><small>BY GEOPRAM TECHNOLOGIES</small></div></a><div class="nav-links" id="navLinks"><a href="#features">Features</a><a href="#how-it-works">How it works</a><a href="templates.html">Templates</a><a href="#about">About Geopram</a></div><div class="nav-actions"><a href="dashboard.html" class="btn btn-outline">Sign in</a><a href="builder.html" class="btn btn-primary">Start creating ↗</a><button class="menu-toggle" id="navToggle" aria-label="Open menu">☰</button></div></div></nav><main><section class="hero"><div class="container hero-grid"><div class="hero-copy"><span class="eyebrow">Forms made useful</span><h1>Ask better questions.<br><span style="color:var(--red)">Get better answers.</span></h1><p>Create polished forms for event feedback, registrations, field data collection, research questionnaires, exams and quizzes — without getting lost in complicated tools.</p><div class="hero-actions"><a href="builder.html" class="btn btn-primary">＋ Create your first form</a><a href="templates.html" class="btn btn-outline">Explore templates →</a><a href="open.html" class="btn btn-outline">Have a form code?</a></div><div class="hero-proof"><div class="proof-dots"><span></span><span></span><span></span></div><span>Built for teams, educators, researchers and field professionals.</span></div></div><div class="hero-art"><div class="float-card top"><div class="float-icon">✓</div><div><strong>Clear, simple forms</strong><small>Designed for every screen</small></div></div><img class="hero-person" src="assets/hero-professional.png" alt="Professional working on a laptop"><div class="float-card bottom"><div class="float-icon">▥</div><div><strong>Responses that inform</strong><small>Turn feedback into next steps</small></div></div></div></div></section><section class="trust-strip"><div class="container trust-inner"><span>ONE WORKSPACE FOR</span><strong>Events & feedback</strong><strong>Field research</strong><strong>Education & quizzes</strong><strong>Customer insights</strong></div></section><section class="section" id="features"><div class="container"><div class="section-heading"><span class="eyebrow">Built for real work</span><h2>More than a form link.</h2><p>Bring data collection, feedback and learning into one straightforward workspace.</p></div><div class="feature-grid"><article class="feature-card"><div class="feature-icon">▤</div><h3>Feedback & registration</h3><p>Collect event registrations, attendee preferences, satisfaction ratings and suggestions with clear, mobile-friendly forms.</p></article><article class="feature-card"><div class="feature-icon">⌖</div><h3>Field data collection</h3><p>Structure field observations, location notes and photo or document attachments for research and project teams.</p></article><article class="feature-card"><div class="feature-icon">✎</div><h3>Quizzes & assessments</h3><p>Create multiple-choice knowledge checks, add correct answers and provide a simple score after submission.</p></article><article class="feature-card"><div class="feature-icon">▧</div><h3>Media-friendly questions</h3><p>Let respondents attach images or files, add video links and include useful context alongside answers.</p></article><article class="feature-card"><div class="feature-icon">◉</div><h3>Insights at a glance</h3><p>Review response counts, browse submissions and export collected demo responses to CSV.</p></article><article class="feature-card"><div class="feature-icon">▣</div><h3>Responsive by design</h3><p>Create and answer forms on desktop, tablet or mobile. The interface adapts to small screens without horizontal page overflow.</p></article></div></div></section><section class="section" id="how-it-works" style="background:#fff"><div class="container"><div class="section-heading"><span class="eyebrow">Three simple steps</span><h2>From idea to useful information.</h2><p>Keep the process practical. Start small, test your questions, then share.</p></div><div class="steps"><div class="step"><span class="step-num">01 / BUILD</span><h3>Choose your questions</h3><p class="muted">Start blank or use a template. Add text, choices, ratings, dates, media and more.</p></div><div class="step"><span class="step-num">02 / SHARE</span><h3>Preview on any device</h3><p class="muted">Check the flow and wording before sharing your form with respondents.</p></div><div class="step"><span class="step-num">03 / LEARN</span><h3>Use what comes back</h3><p class="muted">Review submissions and export records to support your next decision.</p></div></div></div></section><section class="section" id="about"><div class="container"><div class="cta-band"><div><span class="eyebrow" style="color:#ff7e86">Geopram Technologies</span><h2>Practical digital tools for people doing meaningful work.</h2><p>Geopram works across geospatial technology, Earth observation, AI-enabled workflows, software and digital solutions. Geopram Forms brings that practical mindset to everyday data collection.</p></div><a href="builder.html" class="btn btn-primary">Build a form now ↗</a></div></div></section></main><footer class="footer"><div class="container"><div class="footer-grid"><div><a class="brand" href="index.html"><img src="assets/geopram-logo.png" alt="Geopram logo"><div class="brand-name">GEOPRAM <span>FORMS</span><small>BY GEOPRAM TECHNOLOGIES</small></div></a><p style="max-width:300px;margin-top:18px">A simple starting point for collecting feedback, field observations, registrations and learning assessments.</p></div><div><h4>Explore</h4><div class="footer-links"><a href="#features">Features</a><a href="templates.html">Templates</a><a href="dashboard.html">Dashboard</a></div></div><div><h4>Create</h4><div class="footer-links"><a href="builder.html?type=survey">Feedback form</a><a href="builder.html?type=data">Field form</a><a href="builder.html?type=quiz">Quiz</a></div></div><div><h4>Geopram</h4><div class="footer-links"><a href="#about">About us</a><a href="settings.html">Workspace settings</a><a href="responses.html">Response insights</a></div></div></div><div class="copyright"><span>© ${new Date().getFullYear()} Geopram Technologies. All rights reserved.</span><span>Built for the way real teams collect information.</span></div></div></footer><div id="toast" class="toast"></div>`;document.body.innerHTML=content;$('#navToggle').addEventListener('click',()=>$('#navLinks').classList.toggle('open'))}
/* ===== Geopram accounts, unique form codes and approvals ===== */
const gj=(k,d)=>{try{const v=JSON.parse(localStorage.getItem(k));return v??d}catch(e){return d}};
async function gHash(t){try{const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(t));return[...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}catch(e){return btoa(t)}}
let GFU=null;
function gfUser(){const a=gj('gp_adm_s',null);if(a)return{email:a.em,name:'Administrator',role:'admin'};const m=gj('gp_me',null);if(!m)return null;const u=gj('gp_users',{})[m.email];if(!u||u.sus)return null;return{email:m.email,name:u.n||m.n,role:u.role==='tutor'?(u.ap===0?'pending':'tutor'):'learner'}}
function genCode(){const c='ABCDEFGHJKMNPQRSTUVWXYZ23456789',r=n=>Array.from({length:n},()=>c[Math.floor(Math.random()*c.length)]).join('');return 'GF-'+r(4)+'-'+r(4)}
const myForms=db=>GFU.role==='admin'?db.forms:db.forms.filter(f=>f.owner===GFU.email);
const canEdit=f=>GFU&&(GFU.role==='admin'||f.owner===GFU.email);
function apprPill(f){const a=f.approval||'approved';return `<span class="pill ${a==='approved'?'':a==='pending'?'draft':'closed'}">${a==='approved'?'approved':a==='pending'?'awaiting approval':'rejected'}</span>`}
function gateUI(title,msg,extra){document.body.innerHTML=`<div class="form-public"><div class="public-top"><div class="container"><a class="brand" href="index.html"><img src="assets/geopram-logo.png" alt="Geopram Technologies"><div class="brand-name">GEOPRAM <span>FORMS</span><small>BY GEOPRAM TECHNOLOGIES</small></div></a></div></div><div class="public-wrap"><div class="public-form-head"><h1>${title}</h1><p class="muted">${msg}</p></div>${extra||''}</div></div><div id="toast" class="toast"></div>`}
const loginHTML=`<form class="public-question" id="gfLogin"><label class="title" for="gfE">Geopram username (your email)</label><input class="public-control" id="gfE" type="email" required autocomplete="username"><label class="title" for="gfP" style="margin-top:14px">Password</label><input class="public-control" id="gfP" type="password" required autocomplete="current-password"><p class="small" id="gfM" style="color:#c8102e;font-weight:700"></p><div style="display:flex;gap:10px;flex-wrap:wrap"><button class="btn btn-primary" type="submit">Log in</button><a class="btn btn-outline" href="../academy.html">Create a Geopram account</a></div></form>`;
function bindLogin(){const f=$('#gfLogin');if(!f)return;f.onsubmit=async e=>{e.preventDefault();const em=$('#gfE').value.trim().toLowerCase(),h=await gHash($('#gfP').value),M=$('#gfM'),ad=gj('gp_adm',null),U=gj('gp_users',{});
 if(ad&&ad.em===em&&!U[em]){if(ad.h!==h)return M.textContent='Email or password is incorrect.';localStorage.setItem('gp_adm_s',JSON.stringify({em}));location.reload();return}
 const u=U[em];if(!u||u.h!==h)return M.textContent='Email or password is incorrect.';if(u.sus)return M.textContent='This account is suspended. Please contact Geopram.';
 localStorage.setItem('gp_me',JSON.stringify({email:em,n:u.n,ph:u.ph,role:u.role||'learner'}));location.reload()}}
const codeHTML=`<form class="public-question" id="gfCode"><label class="title" for="gfC">Form code</label><input class="public-control" id="gfC" placeholder="GF-XXXX-XXXX" required autocomplete="off" style="text-transform:uppercase"><p class="small" id="gfCM" style="color:#c8102e;font-weight:700"></p><button class="btn btn-primary" type="submit">Open form →</button></form>`;
function gfAccess(f){return GFU&&(GFU.role==='admin'||f.owner===GFU.email||(f.approval==='approved'&&f.status==='published'&&sessionStorage.getItem('gf_ok_'+f.id)==='1'))}
function gfFind(code){const c=(code||'').trim().toUpperCase();return getDB().forms.find(f=>(f.code||'').toUpperCase()===c)}
function gfCheck(f){if(!f)return 'That code was not found. Check it and try again.';if(f.approval!=='approved')return 'This form is waiting for Geopram approval.';if(f.status!=='published')return 'This form is not accepting responses right now.';return ''}
function gfCodeGate(f){const bad=gfCheck(f);if(bad){gateUI('Form not available',bad,'<a class="btn btn-outline" href="open.html">Enter another code</a>');return}
 gateUI('Enter the form code','This form is protected. Ask the person who shared it for the code.',codeHTML);$('#gfCode').onsubmit=e=>{e.preventDefault();if(($('#gfC').value||'').trim().toUpperCase()!==f.code.toUpperCase())return $('#gfCM').textContent='That code is not correct.';sessionStorage.setItem('gf_ok_'+f.id,'1');location.reload()}}
function initOpen(){gateUI('Open a form','Enter the unique code you were given. You are signed in as '+esc(GFU.name)+'.',codeHTML);$('#gfCode').onsubmit=e=>{e.preventDefault();const f=gfFind($('#gfC').value),bad=gfCheck(f);if(bad)return $('#gfCM').textContent=bad;sessionStorage.setItem('gf_ok_'+f.id,'1');location.href='preview.html?id='+encodeURIComponent(f.id)}}
function approvalPanel(db){if(GFU.role!=='admin')return '';const p=db.forms.filter(f=>f.approval==='pending');return `<section class="panel" style="margin-bottom:20px"><div class="panel-heading"><h3>Awaiting approval</h3><span class="small muted">${p.length} form${p.length===1?'':'s'}</span></div>${p.length?p.map(f=>`<div class="activity-row"><div class="activity-copy"><strong>${esc(f.title)}</strong><small>By ${esc(f.ownerName||f.owner)} · Code ${esc(f.code)}</small></div><a class="btn btn-outline btn-sm" href="preview.html?id=${encodeURIComponent(f.id)}" target="_blank">Review</a><button class="btn btn-primary btn-sm" data-appr="${f.id}|approved">Approve</button><button class="btn btn-outline btn-sm" data-appr="${f.id}|rejected">Reject</button></div>`).join(''):'<p class="muted">Nothing is waiting for approval.</p>'}</section>`}
document.addEventListener('click',e=>{const a=e.target.closest('[data-appr]');if(a&&GFU&&GFU.role==='admin'){const [id,v]=a.dataset.appr.split('|'),db=getDB(),f=db.forms.find(x=>x.id===id);if(f){f.approval=v;saveDB(db);location.reload()}}
 if(e.target.closest('#gfOut')){localStorage.removeItem('gp_me');localStorage.removeItem('gp_adm_s');location.href='../index.html'}
 const c=e.target.closest('[data-copy]');if(c){try{navigator.clipboard.writeText(c.dataset.copy)}catch(_){}toast('Form code: '+c.dataset.copy)}});
const GF_BACK='<div style="display:flex;gap:10px;flex-wrap:wrap"><a class="btn btn-outline" href="open.html">Enter a form code</a><a class="btn btn-outline" href="../index.html">Back to Geopram</a></div>';
document.addEventListener('DOMContentLoaded',()=>{const page=document.body.dataset.page;GFU=gfUser();
 const need={dashboard:'build',builder:'build',templates:'build',responses:'build',settings:'admin',preview:'any',open:'any'}[page];
 if(need){if(!GFU){gateUI('Sign in to continue','Use your Geopram username (email) and password. You need an account to build or open forms.',loginHTML);bindLogin();return}
  if(need==='build'&&GFU.role!=='admin'&&GFU.role!=='tutor'){gateUI(GFU.role==='pending'?'Tutor approval pending':'Tutors and admins only',GFU.role==='pending'?'Your tutor account is waiting for approval. You can build forms as soon as Geopram approves it.':'Forms can be built by approved tutors and admins. You can still open a form with a code.',GF_BACK);return}
  if(need==='admin'&&GFU.role!=='admin'){gateUI('Admin only','Only the administrator can open workspace settings.',GF_BACK);return}}
 ({landing:initLanding,dashboard:initDashboard,builder:initBuilder,templates:initTemplates,preview:initPreview,responses:initResponses,settings:initSettings,open:initOpen}[page]||initLanding)()});
